                value = value + rhs if op == "+" else value - rhs
            else:
                break
        return value

    def parse_term():
        nonlocal pos
        value = parse_factor()
        while True:
            skip_ws()
            if pos < n and text[pos] in "*/":
                op = text[pos]
                pos += 1
